import { type } from 'arktype';

/** Every primary key is a uuidv7 generated by the application (Postgres 17 has no uuidv7()). */
export const Uuid = type('string.uuid');
export type Uuid = typeof Uuid.infer;

/** An ActivityPub id: an absolute URL, stored immutably beside the local uuid. */
export const ApId = type('string.url');
export type ApId = typeof ApId.infer;

/** One actor table holds both; Application is the instance actor, Service a remote bot. */
export const ActorKind = type("'Person' | 'Group' | 'Application' | 'Service'");
export type ActorKind = typeof ActorKind.infer;

/** Timestamps cross JSON boundaries (views, events) as ISO 8601 strings. */
export const IsoDate = type('string.date.iso');
export type IsoDate = typeof IsoDate.infer;

/** A reference to a post or a comment, the two things that can be voted on or reported. */
export const ContentRef = type({ kind: "'post' | 'comment'", id: Uuid });
export type ContentRef = typeof ContentRef.infer;
